/* Euno -- The Quiet Room.
   Flat at rest, soft on lift, one blue, motion only as confirmation.
   Every value here is deliberate; see DESIGN.md for the rules. */

/* ---------------------------------------------------------------- tokens */

:root {
  --bg: #f5f5f7;
  --surface: #ffffff;
  --text: #1d1d1f;
  --muted: #6e6e73;
  /* accent: fills and focus. accent-text: tinted text, holds 4.5:1 on bg. */
  --accent: #0071e3;
  --accent-fill: #0071e3;
  --accent-text: #0069d5;
  --danger: #d70015;
  --border: rgba(0, 0, 0, 0.08);
  --field-bg: var(--surface);
  --shadow-float: 0 12px 40px rgba(0, 0, 0, 0.12);
  --header-bg: rgba(245, 245, 247, 0.78);

  --radius: 16px;
  --radius-lg: 24px;

  /* Motion. Strong ease-out for anything entering or responding;
     ease-in-out only for on-screen movement (the name morph). */
  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --t-fast: 140ms;
  --t-med: 220ms;
  --t-screen: 260ms;
  --t-slow: 420ms;

  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #000000;
    --surface: #1c1c1e;
    --text: #f5f5f7;
    --muted: #98989d;
    /* Tinted text can afford the brighter blue; filled buttons keep the
       deeper one so white labels hold 4.7:1. */
    --accent: #0a84ff;
    --accent-fill: #0071e3;
    --accent-text: #0a84ff;
    --danger: #ff453a;
    --border: rgba(255, 255, 255, 0.1);
    --shadow-float: 0 12px 40px rgba(0, 0, 0, 0.55);
    --header-bg: rgba(0, 0, 0, 0.72);
  }
}

/* ------------------------------------------------------------------ base */

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 17px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -webkit-text-size-adjust: 100%;
  -webkit-tap-highlight-color: transparent;
}

::selection {
  background: color-mix(in srgb, var(--accent) 25%, transparent);
}

input,
textarea {
  caret-color: var(--accent);
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  touch-action: manipulation;
  user-select: none;
}

/* Visible keyboard focus everywhere. The transparent outline stays visible
   in forced-colors mode, where box-shadow disappears. */
:focus-visible {
  outline: 2px solid transparent;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 45%, transparent);
}

/* ----------------------------------------------------------------- shell */

/* Invisible 1px marker at the very top of the page; when it leaves the
   viewport, content is under the header and the hairline switches on. */
.scroll-sentinel {
  position: absolute;
  top: 0;
  width: 1px;
  height: 1px;
}

.app-header {
  position: sticky;
  top: 0;
  z-index: 10;
  background: var(--header-bg);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
  backdrop-filter: blur(20px) saturate(180%);
  border-bottom: 1px solid transparent;
  transition: border-color var(--t-med) var(--ease-out);
  view-transition-name: app-header;
}

/* The hairline exists only once content has scrolled under the material. */

