  animation: wl-enter-up 640ms var(--ease-out) 130ms both;
}

.wl-joined {
  animation: wl-rise-in 500ms var(--ease-out) both;
}

@media (prefers-reduced-motion: reduce) {
  .wl-top,
  .wl-bottom,
  .wl-joined,
