11	// One row per (userId, action). A function with more than one window (e.g.
12	// a per-minute AND a per-day cap) calls this once per window with distinct
13	// action names, e.g. "createCapture:minute" and "createCapture:day".
14	export async function checkRateLimit(
15	  ctx: MutationCtx,
16	  userId: string,
17	  action: string,
18	  max: number,
19	  windowMs: number,
20	): Promise<void> {
21	  const now = Date.now();
22	  const existing = await ctx.db
23	    .query("rateLimits")
24	    .withIndex("by_user_action", (q) =>
25	      q.eq("userId", userId).eq("action", action),
26	    )
27	    .unique();
28	
29	  if (existing === null) {
30	    await ctx.db.insert("rateLimits", {
31	      userId,
32	      action,
33	      windowStart: now,
34	      count: 1,
35	    });
36	    return;
37	  }
38	
39	  if (now - existing.windowStart >= windowMs) {
40	    // Past the window: start a fresh one rather than accumulate forever.
41	    await ctx.db.patch("rateLimits", existing._id, {
42	      windowStart: now,
43	      count: 1,
44	    });
45	    return;
46	  }
47	
48	  if (existing.count >= max) {
49	    throw new Error("Too many requests -- please wait a moment");
50	  }
51	
52	  await ctx.db.patch("rateLimits", existing._id, {
53	    count: existing.count + 1,
