  -webkit-appearance: none;
  appearance: none;
  transition: border-color var(--t-fast) var(--ease-out),
    background var(--t-fast) var(--ease-out);
}

.wl-field::placeholder {
  color: #6e6e73;
}

.wl-field:hover {
  border-color: rgba(255, 255, 255, 0.13);
}

.wl-field:focus {
  outline: none;
  border-color: rgba(255, 255, 255, 0.3);
  background: rgba(0, 0, 0, 0.22);
}

input.old_string:
@media (prefers-reduced-motion: reduce) {
  .wl-top,
  .wl-bottom,
  .wl-joined,
  .wl-check {
    animation: none;
  }
}

input.new_string:
@media (prefers-reduced-motion: reduce) {
  .wl-top,
  .wl-bottom,
  .wl-joined,
  .wl-check {
    animation: none;
  }
  /* The email row still appears on cue -- it just snaps instead of sliding. */
  .wl-email-wrap,
  .wl-go-name {
    transition: none;
  }
}
